Object.assign(window.TEM8_DICTIONARY, {"symbolic":{"media":{"uk":"media/uk/symbolic__gb_1.mp3","us":"media/us/symbolic__us_1.mp3"},"oxford":{"phon":"sɪmˈbɒlɪk","pos":"adjective","senses":[{"en":"containing symbols, or being used as a symbol","cn":"使用象征的；作为象征的；象征性的","ex":{"en":"He shook his fist in a symbolic gesture of defiance.","cn":"他做了一个象征性的挑战手势－挥了挥他的拳头。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(事件、行动、程序)象征的，象征性的","en":"If you describe an event, action, or procedure as symbolic, you mean that it represents an important change, although it has little practical effect.","ex":{"en":"A lot of Latin-American officials are stressing the symbolic importance of the trip","cn":"许多拉丁美洲的官员都在强调此行的重要象征意义。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"象征…的;作为…的象征的","en":"Something that is symbolic of a person or thing is regarded or used as a symbol of them.","ex":{"en":"Yellow clothes are worn as symbolic of spring","cn":"穿上黄色的衣服象征着春天来了。"}},{"pos":"ADJ 形容词","cn":"符号的;记号的","en":"Symbolic is used to describe things involving or relating to symbols.","ex":{"en":"...symbolic representations of landscape.","cn":"地貌的符号化呈现"}}]},"examples":[{"en":"The Channel Tunnel has enormous symbolic significance for a united Europe.","cn":"英吉利海峡隧道对于建立一个统一的欧洲具有重大的象征意义。"},{"en":"The new regulations are largely symbolic (= they will not have any real effect).","cn":"新的制度基本上是象征性的。"}]},"symptom":{"oxford":{"phon":"ˈsɪmptəm","pos":"noun","senses":[{"en":"a change in your body or mind that shows that you are not healthy","cn":"症状","ex":{"en":"Symptoms include a headache and sore throat.","cn":"症状包括头痛和咽喉疼痛。"}},{"en":"a sign that something exists, especially something bad","cn":"征候；征兆","ex":{"en":"The rise in inflation was just one symptom of the poor state of the economy.","cn":"通胀上升不过是经济不景气的一个征候。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"症状","en":"A symptom of an illness is something wrong with your body or mind that is a sign of the illness.","ex":{"en":"One of the most common symptoms of schizophrenia is hearing imaginary voices.","cn":"精神分裂症的最常见的一个症状就是幻听。"}},{"pos":"N-COUNT 可数名词","cn":"征候;征兆","en":"A symptom of a bad situation is something that happens which is considered to be a sign of this situation.","ex":{"en":"Your problem with keeping boyfriends is just a symptom of a larger problem: making and keeping friends","cn":"你在维系同男友的关系时遭遇的困难暴露了一个更大的问题：如何结交朋友和维持友谊。"}}]},"media":{"uk":"media/uk/symptom__gb_1.mp3","us":"media/us/symptom__us_1.mp3"},"examples":[{"en":"The rise in inflation was just one symptom of the poor state of the economy.","cn":"通胀上升不过是经济不景气的一个征候。"},{"en":"Symptoms include a headache and sore throat.","cn":"症状包括头痛和咽喉疼痛。"}]},"symmetrically":{"oxford":{"phon":"sɪˈmetrɪkli","pos":"adverb","senses":[{"en":"in a way that has two halves, parts or sides of the same size and shape","cn":"对称地","ex":{"en":"Look for trees with branches arranged symmetrically around the trunk.","cn":"寻找树木，其树枝围绕树干对称排列。"}}]},"media":{"uk":"media/uk/symmetrically__gb_1.mp3","us":"media/us/symmetrically__us_1.mp3"},"examples":[{"en":"The pattern was perfectly symmetrical.","cn":""}]},"sympathetic":{"media":{"uk":"media/uk/sympathetic__gb_1.mp3","us":"media/us/sympathetic__us_1.mp3"},"oxford":{"phon":"ˌsɪmpəˈθetɪk","pos":"adjective","senses":[{"en":"kind to somebody who is hurt or sad; showing that you understand and care about their problems","cn":"同情的；有同情心的；表示同情的","ex":{"en":"a sympathetic listener","cn":"体恤别人的听者"}},{"en":"showing that you approve of somebody/something or that you share their views and are willing to support them","cn":"赞同的；支持的","ex":{"en":"He was speaking to a highly sympathetic audience.","cn":"他正在对他的铁杆支持者演讲。"}},{"en":"easy to like","cn":"让人喜欢的；招人喜爱的","ex":{"en":"a sympathetic character in a novel","cn":"小说中一个讨人喜欢的人物"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"同情的;表示同情的","en":"If you are sympathetic to someone who is in a bad situation, you are kind to them and show that you understand their feelings.","ex":{"en":"She was very sympathetic to the problems of adult students","cn":"她对成年学生的问题深表同情。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"赞同的;支持的","en":"If you are sympathetic to a proposal or action, you approve of it and are willing to support it.","ex":{"en":"She met people in London who were sympathetic to the Indian freedom struggle","cn":"她在伦敦结识了一些支持印度独立运动的人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"讨人喜欢的;合意的","en":"You describe someone as sympathetic when you like them and approve of the way that they behave.","ex":{"en":"She sounds a most sympathetic character.","cn":"她听起来是个很招人喜欢的人物。"}}]},"examples":[{"en":"I'm here if you need a sympathetic ear (= sb to talk to about your problems).","cn":"要是你想诉诉苦，那就跟我说吧。"},{"en":"We hope this application will be treated sympathetically (= it will be approved).","cn":"我们希望这份申请能得到批准。"}]},"syllabus":{"media":{"uk":"media/uk/syllabus__gb_1.mp3","us":"media/us/syllabus__us_1.mp3"},"oxford":{"phon":"ˈsɪləbəs","pos":"noun","senses":[{"en":"a list of the topics, books, etc. that students should study in a particular subject at school or college","cn":"教学大纲","lab":"British English","ex":{"en":"American history will be on the syllabus next term.","cn":"下学期美国历史将列入教学大纲。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"课程大纲","en":"You can refer to the subjects that are studied in a particular course as the syllabus .","ex":{"en":"...the GCSE history syllabus.","cn":"英国中等教育证书考试的历史大纲"}},{"pos":"N-COUNT 可数名词","cn":"(课程的)提纲,摘要","en":"A syllabus is an outline or summary of the subjects to be covered in a course."}]},"examples":[{"en":"Two Shakespeare plays are on this year’s English syllabus.","cn":"今年的英语课程大纲上有两部莎士比亚剧作。"}]},"syntax":{"media":{"uk":"media/uk/syntax__gb_1.mp3","us":"media/us/syntax__us_1.mp3"},"oxford":{"phon":"ˈsɪntæks","pos":"noun","senses":[{"en":"the way that words and phrases are put together to form sentences in a language; the rules of grammar for this","cn":"句法；句法规则","lab":"linguistics"},{"en":"the rules that state how words and phrases must be used in a computer language","cn":"语法；句法；语构","lab":"computing","ex":{"en":"The instructions were not carried out because of a syntax error.","cn":"由于语法错误，指令未执行。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"句法规则;句法","en":"Syntax is the ways that words can be put together, or are put together, in order to make sentences.","ex":{"en":"His grammar and syntax, both in oral and written expression, were much better than the average.","cn":"无论口头还是笔头，他的文法和句法都非常出众。"}}]}},"system":{"media":{"uk":"media/uk/system__gb_1.mp3","us":"media/us/system__us_1.mp3"},"oxford":{"phon":"ˈsɪstəm","pos":"noun","senses":[{"en":"an organized set of ideas or theories or a particular way of doing something","cn":"（思想或理论）体系；方法；制度；体制","g":"[countable]","ex":{"en":"reform of the country's education system","cn":"国家教育体制改革"}},{"en":"a group of things, pieces of equipment, etc. that are connected or work together","cn":"系统","g":"[countable]","ex":{"en":"They installed a security system but it failed.","cn":"他们安装了安全系统，但没起作用。"}},{"en":"a set of computer equipment and programs that are used together","cn":"（计算机）系统","g":"[countable]","ex":{"en":"to develop a new computer system","cn":"开发新的计算机系统"}},{"en":"a human or an animal body, or a part of it, when it is being thought of as the organs and processes that make it function","cn":"身体；（器官）系统","g":"[countable]","ex":{"en":"Wait until the drugs have passed through your system.","cn":"等到药物排出体外。"}},{"en":"the rules or people that control a country or an organization, especially when they seem to be unfair because you cannot change them","cn":"（尤指不公正的统治或管理）制度，体系，集团","g":"[singular]","lab":"informal, usually disapproving，，","ex":{"en":"You can't beat the system (= you must accept it).","cn":"你斗不过现行的体制。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"体系;制度;体制;组织","en":"A system is a way of working, organizing, or doing something which follows a fixed plan or set of rules. You can use system to refer to an organization or institution that is organized in this way.","ex":{"en":"The present system of funding for higher education is unsatisfactory.","cn":"目前高等教育的经费体制并不令人满意。"}},{"pos":"N-COUNT 可数名词","cn":"(计算机、警报器等的)系统","en":"A system is a set of devices powered by electricity, for example a computer or an alarm.","ex":{"en":"Viruses tend to be good at surviving when a computer system crashes.","cn":"计算机病毒在系统崩溃后往往依然存在。"}},{"pos":"N-COUNT 可数名词","cn":"(水管或电线等的)系统","en":"A system is a set of equipment or parts such as water pipes or electrical wiring, which is used to supply water, heat, or electricity.","ex":{"en":"...a central heating system.","cn":"中央供暖系统"}},{"pos":"N-COUNT 可数名词","cn":"(交通、通信)网，网络","en":"A system is a network of things that are linked together so that people or things can travel from one place to another or communicate.","ex":{"en":"...Australia's road and rail system.","cn":"澳大利亚的公路网和铁路网"}},{"pos":"N-COUNT 可数名词","cn":"身体;(器官)系统","en":"Your system is your body's organs and other parts that together perform particular functions.","ex":{"en":"He had slept for over fourteen hours, and his system seemed to have recuperated admirably","cn":"他已睡了超过 14 个小时了，他的身体恢复得很不错。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指数学或科学中的)体系,体制","en":"A system is a particular set of rules, especially in mathematics or science, which is used to count or measure things.","ex":{"en":"...the decimal system of metric weights and measures.","cn":"公制度量衡的十进制"}},{"pos":"N-SING 单数名词","cn":"政府;现行体制;公共行政","en":"People sometimes refer to the government or administration of a country as the system .","ex":{"en":"These feelings are likely to make people attempt to overthrow the system","cn":"这些情绪有可能促使人们想要推翻现行的体制。"}},{"pos":"PHRASE 短语","cn":"宣泄;排解;戒掉;让…淡出自己的生活","en":"If you get something out of your system, you take some action so that you no longer want to do it or no longer have strong feelings about it.","ex":{"en":"I want to get boxing out of my system and settle down to enjoy family life.","cn":"我想结束拳击生涯，安定下来享受家庭生活。"}}]},"examples":[{"en":"I was very angry with him, but now I feel I've got it out of my system.","cn":"我当时很生他的气，不过现在我感觉气已经消了。"},{"en":"You have to wait until the drugs have passed out of your system.","cn":"你必须等到药物排出体外。"}]},"syndrome":{"media":{"uk":"media/uk/syndrome__gb_1.mp3","us":"media/us/syndrome__us_1.mp3"},"oxford":{"phon":"ˈsɪndrəʊm","pos":"noun","senses":[{"en":"a set of physical conditions that show you have a particular disease or medical problem","cn":"综合征；综合症状","ex":{"en":"PMS or premenstrual syndrome","cn":"经前综合征"}},{"en":"a set of opinions or a way of behaving that is typical of a particular type of person, attitude or social problem","cn":"典型意见；典型表现","ex":{"en":"With teenagers, be prepared for the ‘Me, me, me!’ syndrome (= they think of themselves first).","cn":"跟青少年在一起，对他们那种凡事只想到“我、我、我！”的典型心理不要大惊小怪。"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"综合征;综合症状","en":"A syndrome is a medical condition that is characterized by a particular group of signs and symptoms.","ex":{"en":"Irritable bowel syndrome seems to affect more women than men","cn":"女性比男性更易患肠易激综合征。"}},{"pos":"N-COUNT 可数名词","cn":"(不良情况的)典型表现，典型行为","en":"You can refer to an undesirable condition that is characterized by a particular type of activity or behaviour as a syndrome .","ex":{"en":"It's a bit like the exam syndrome where you write down everything you know regardless of what has been asked","cn":"不论问题是什么就把所知道的统统写上，这有些像典型的考试心理。"}}]},"examples":[{"en":"With teenagers, be prepared for the ‘Me, me, me!’ syndrome (= they think of themselves first).","cn":"跟青少年在一起，对他们那种凡事只想到“我、我、我！”的典型心理不要大惊小怪。"},{"en":"This syndrome is associated with frequent coughing.","cn":"这种综合征与经常咳嗽有关。"}]},"symbol":{"media":{"uk":"media/uk/symbol__gb_1.mp3","us":"media/us/symbol__us_1.mp3"},"oxford":{"phon":"ˈsɪmbl","pos":"noun","senses":[{"en":"a person, an object, an event, etc. that represents a more general quality or situation","cn":"象征","ex":{"en":"The vase is decorated with religious symbols.","cn":"花瓶上饰有含宗教象征的图案。"}},{"en":"a sign, number, letter, etc. that has a fixed meaning, especially in science, mathematics and music","cn":"符号；代号；记号","ex":{"en":"the mathematical symbol for infinity","cn":"表示无穷大的数学符号"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"象征;代表","en":"Something that is a symbol of a society or an aspect of life seems to represent it because it is very typical of it.","ex":{"en":"To them, the monarchy is the special symbol of nationhood","cn":"对他们来说，君主政体是国家地位的特殊象征。"}},{"pos":"N-COUNT 可数名词","cn":"象征物;标志","en":"A symbol of something such as an idea is a shape or design that is used to represent it.","ex":{"en":"Later in this same passage Yeats resumes his argument for the Rose as an Irish symbol","cn":"随后在同一篇诗歌里，叶芝再次将玫瑰作为爱尔兰的标志。"}},{"pos":"N-COUNT 可数名词","cn":"符号;代号;记号","en":"A symbol for an item in a calculation or scientific formula is a number, letter, or shape that represents that item.","ex":{"en":"What's the chemical symbol for mercury?","cn":"汞的化学元素符号是什么？"}}]},"examples":[{"en":"A list of symbols used on the map is given in the index.","cn":"这份地图所使用的符号全部列在索引中。"},{"en":"White has always been a symbol of purity in Western cultures.","cn":"在西方文化中，白色一向象征纯洁。"}]},"symptoms":{"lemma":"symptom"},"systematically":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"trying to avoid mistakes and do everything correctly by paying a lot of attention to details","cn":""},{"en":"always doing things in a careful and well-organized way","cn":""}]},"media":{"uk":"media/uk/systematically__gb_1.mp3","us":"media/us/systematically__us_1.mp3"},"oxford":{"phon":"ˌsɪstəˈmætɪkli","pos":"adverb","senses":[{"en":"in a complete, efficient or determined way that follows a system or plan","cn":"系统地：遵循系统或计划的完整，有效或确定的方式","ex":{"en":"The search was carried out systematically.","cn":"搜索工作做得有条不紊。"}}]}},"systematic":{"media":{"uk":"media/uk/systematic__gb_1.mp3","us":"media/us/systematic__us_1.mp3"},"oxford":{"phon":"ˌsɪstəˈmætɪk","pos":"adjective","senses":[{"en":"done according to a system or plan, in a complete, efficient or determined way","cn":"成体系的；系统的；有条理的；有计划有步骤的","ex":{"en":"a systematic approach to solving the problem","cn":"系统地解决问题的办法"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"成体系的;系统的;有条理的;按既定计划的","en":"Something that is done in a systematic way is done according to a fixed plan, in a thorough and efficient way.","ex":{"en":"They went about their business in a systematic way","cn":"他们按部就班地做生意。"}}]},"examples":[{"en":"a systematic attempt to destroy the organization","cn":"力图摧毁那个组织的有计划有步骤的行动"},{"en":"a systematic approach to solving the problem","cn":"系统地解决问题的办法"}]},"sync":{"oxford":{"phon":"sɪŋk","pos":"verb","senses":[{"en":"to happen at the same time or to move at the same speed as something; to make something do this","cn":"（使）同步，在时间上一致，同速进行","ex":{"en":"The live music isn't synced to the visuals.","cn":"现场音乐跟画面不同步。"}},{"en":"to link data files between one computer or mobile device and another so that the information in the files on both machines is the same","cn":"使同步，使一致（使数据在不同的计算机或移动电子设备上同步更新）","ex":{"en":"How do I sync email across all my devices?","cn":"怎样在所有设备上同步电邮？"}}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"不协调/协调;不同步/同步","en":"If two things are out of sync, they do not match or do not happen together as they should. If two things are in sync, they match or happen together as they should.","ex":{"en":"Normally, when demand and supply are out of sync, you either increase the supply, or you adjust the price mechanism","cn":"通常，当供需失衡时，要么加大供给，要么调整价格机制。"}}]},"media":{"uk":"media/uk/sync__gb_1.mp3","us":"media/us/sync__us_1.mp3"},"examples":[{"en":"His opinions were in sync with those of his colleagues.","cn":"他的看法和同事的一致。"},{"en":"The soundtrack is not in sync with the picture.","cn":"声迹与画面不同步。"}]},"sympathy":{"oxford":{"phon":"ˈsɪmpəθi","pos":"noun","senses":[{"en":"the feeling of being sorry for somebody; showing that you understand and care about somebody’s problems","cn":"同情","g":"[uncountable, countable, usually plural]","lab":"formal","ex":{"en":"to express/feel sympathy for somebody","cn":"向某人表示体恤；对某人感到同情"}},{"en":"the act of showing support for or approval of an idea, a cause, an organization, etc.","cn":"赞同；支持","g":"[uncountable, countable, usually plural]","ex":{"en":"The seamen went on strike in sympathy with (= to show their support for) the dockers.","cn":"海员举行罢工，以表示对码头工人的支持。"}},{"en":"friendship and understanding between people who have similar opinions or interests","cn":"意气相投；志同道合","g":"[uncountable]","ex":{"en":"There was no personal sympathy between them.","cn":"他们个人之间全无相投之处。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同情心;同情","en":"If you have sympathy for someone who is in a bad situation, you are sorry for them, and show this in the way you behave towards them.","ex":{"en":"We expressed our sympathy for her loss","cn":"我们对她的损失表示同情。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(对观点、看法的)同意,支持","en":"If you have sympathy with someone's ideas or opinions, you agree with them.","ex":{"en":"I have some sympathy with this point of view","cn":"我比较同意这个观点。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"支持","en":"If you take some action in sympathy with someone else, you do it in order to show that you support them.","ex":{"en":"Several hundred workers struck in sympathy with their colleagues","cn":"几百名工人罢工以声援他们的同事。"}}]},"media":{"uk":"media/uk/sympathy__gb_1.mp3","us":"media/us/sympathy__us_1.mp3"},"examples":[{"en":"The seamen went on strike in sympathy with (= to show their support for) the dockers.","cn":"海员举行罢工，以表示对码头工人的支持。"},{"en":"( formal ) May we offer our deepest sympathies on the death of your wife.","cn":"我们谨对尊夫人去世表示最深切的慰唁。"}]},"symmetrical":{"media":{"uk":"media/uk/symmetrical__gb_1.mp3","us":"media/us/symmetrical__us_1.mp3"},"oxford":{"phon":"sɪˈmetrɪkl","pos":"adjective","senses":[{"en":"having two halves, parts or sides that are the same in size and shape","cn":"对称的","ex":{"en":"a symmetrical pattern","cn":"对称的图案"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"对称的","en":"If something is symmetrical, it has two halves which are exactly the same, except that one half is the mirror image of the other.","ex":{"en":"...the neat rows of perfectly symmetrical windows.","cn":"一排排整齐而且完全对称的窗子"}}]},"examples":[{"en":"a symmetrical pattern","cn":"对称的图案"},{"en":"The pattern was perfectly symmetrical.","cn":"该图案完全对称。"}]},"systems":{"lemma":"system"},"symbolizes":{"lemma":"symbolize"},"symphonies":{"lemma":"symphony"},"symbols":{"lemma":"symbol"},"synthetic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"合成的;人造的","en":"Synthetic products are made from chemicals or artificial substances rather than from natural ones.","ex":{"en":"Boots made from synthetic materials can usually be washed in a machine.","cn":"合成材料制成的靴子通常可以机洗。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not real or natural, but made to look or work like something real or natural","cn":""},{"en":"made using chemical processes rather than by natural processes","cn":""},{"en":"made by people – used especially about geographical features and materials","cn":""}]},"vocab":{"pos":"1 n adj 2 adj","senses":[{"en":"Something made of artificial material, not natural items, can be described as synthetic . Football stadiums have synthetic grass, just as many aging actresses have synthetic body parts."}]},"media":{"uk":"media/ldoce/hwd/bre/1/synthetic0205.mp3","us":"media/ldoce/hwd/ame/f/synthetic.mp3"},"examples":[{"en":"cotton fabrics and synthetics","cn":"棉织物与合成织物"},{"en":"synthetic drugs/fabrics","cn":"合成药物/织物"}],"oxford":{"phon":"sɪnˈθetɪk","pos":"adjective","senses":[{"en":"artificial; made by combining chemical substances rather than being produced naturally by plants or animals","cn":"人造的；（人工）合成的","ex":{"en":"synthetic drugs/fabrics","cn":"合成药物／织物"}},{"en":"using changes to the ends of words rather than separate words to show the functions of words in a sentence","cn":"综合（型）的","lab":"linguistics"},{"en":"an artificial substance or material","cn":"合成物；合成纤维（织物）；合成剂","ex":{"en":"cotton fabrics and synthetics","cn":"棉织物与合成织物"},"pos":"noun"}]}},"symbiosis":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"共生(关系)","en":"Symbiosis is a close relationship between two organisms of different kinds which benefits both organisms.","ex":{"en":"...the link between bacteria, symbiosis, and the evolution of plants and animals.","cn":"细菌、共生和动植物进化之间的联系"}},{"pos":"N-UNCOUNT 不可数名词","cn":"互惠互利的关系;共赢关系","en":"Symbiosis is any relationship between different things, people, or groups that benefits all the things or people concerned.","ex":{"en":"...the cosy symbiosis of the traditional political parties.","cn":"传统政党间友好的互惠互利关系"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a relationship between people or organizations that depend on each other equally 〔","cn":"人与人之间或机构之间平等的〕互相依赖（关系）"},{"en":"the relationship between different living things that depend on each other 〔","cn":"生物的〕共生（关系）"}]},"vocab":{"pos":"n","senses":[{"en":"Symbiosis , a noun, tells about the relationship between living things that helps all of them stay alive, like the symbiosis between bees that eat nectar from flowers that get cross-pollinated when the bees move from one to the next."}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41symbiosis.mp3","us":"media/ldoce/hwd/ame/9/symbiosis.mp3"},"examples":[{"en":"a symbiotic relationship","cn":"一种互惠互利的关系"}],"oxford":{"phon":"ˌsɪmbaɪˈəʊsɪs","pos":"noun","senses":[{"en":"the relationship between two different living creatures that live close together and depend on each other in particular ways, each getting particular benefits from the other","cn":"共生（关系）","lab":"biology","ex":{"en":"The birds live in symbiosis with the cattle, picking insects from their skin to eat.","cn":"鸟类与牛共生，从牛的皮肤上拾取昆虫来吃。"}},{"en":"a relationship between people, companies, etc. that is to the advantage of both","cn":"合作关系；互惠互利的关系","ex":{"en":"She imagined us living in a perfect mother and daughter symbiosis.","cn":"她想象我们生活在完美的母女共生中。"}}]}},"symphony":{"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"(通常由四个乐章组成的)交响乐，交响曲","en":"A symphony is a piece of music written to be played by an orchestra. Symphonies are usually made up of four separate sections called movements."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long piece of music usually in four parts, written for an orchestra","cn":"交响乐﹐交响曲"},{"en":"a large group of classical musicians led by a conductor","cn":"交响乐团"}]},"vocab":{"pos":"n","senses":[{"en":"A symphony is the name of a type of classical music (a long, complex sonata) and the large orchestra that plays that music."}]},"collocations":{"phrases":["ADJ. Beethoven's 5th, Dvorak's 7th, etc. | C major, D minor, etc.","VERB + SYMPHONY compose, write | conduct, perform, play Bruckner's Symphony No. 5, conducted by Hugh Wolff","SYMPHONY + NOUN orchestra the Chicago Symphony Orchestra | concert","PHRASES symphony No. 2, etc."]},"media":{"uk":"media/ldoce/hwd/bre/f/symphony0205.mp3","us":"media/ldoce/hwd/ame/6/l3symphony.mp3"},"examples":[{"en":"Beethoven's Fifth Symphony","cn":"贝多芬的第五交响曲"},{"en":"Mozart's symphonic works","cn":"莫扎特的交响乐作品"}],"oxford":{"phon":"ˈsɪmfəni","pos":"noun","senses":[{"en":"a long, complicated piece of music for a large orchestra, in three or four main parts (called movements)","cn":"交响乐；交响曲","lab":"British English","ex":{"en":"Beethoven’s Fifth Symphony","cn":"贝多芬的第五交响曲"}}]}},"sympathizer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"赞同者;支持者","en":"The sympathizers of an organization or cause are the people who approve of it and support it.","ex":{"en":"These villagers are guerrilla sympathizers.","cn":"这些村民拥护游击队。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who supports a person, political party, or idea","cn":""},{"en":"all the people who support a person, group, or plan","cn":""},{"en":"someone who supports the ideas of a political organization but does not belong to it, especially an organization that is illegal","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Someone who's on your side, who supports you wholeheartedly, is your sympathizer ."}]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdesympathizer.mp3","us":"media/ldoce/hwd/ame/8/laadsympathizer.mp3"},"examples":[{"en":"communist sympathizers","cn":"共产主义的拥护者"},{"en":"The anti-abortion rally attracted many sympathizers.","cn":"反堕胎集会吸引了很多支持者。"}],"oxford":{"phon":"ˈsɪmpəθaɪzə(r)","pos":"noun","senses":[{"en":"a person who supports or approves of somebody/something, especially a political cause or party","cn":"赞同者；支持者","ex":{"en":"communist sympathizers","cn":"共产主义的拥护者"}}]}},"systematize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使系统化;使成体系;使条理化","en":"If you systematize things, you make them organized.","ex":{"en":"You need to systematize your approach to problem solving.","cn":"你需要采用有条理的方法解决问题。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to put facts, numbers, ideas etc into a particular order","cn":"使条理化﹐使系统化"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41systematize.mp3","us":"media/ldoce/hwd/ame/d/systematize.mp3"},"oxford":{"phon":"ˈsɪstəmətaɪz","pos":"verb","senses":[{"en":"to arrange something according to a system","cn":"使系统化；使成体系；使条理化"}]}},"sycamore":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"西卡莫;西卡莫槭;假挪威槭","en":"A sycamore or a sycamore tree is a tree that has yellow flowers and large leaves with five points.","ex":{"en":"The furniture is made of sycamore, beech and leather.","cn":"这套家具是由西卡莫木材、山毛榉木材以及皮革制成的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a European tree that has leaves with five points and seeds with two parts like wings, or the wood of this tree 〔","cn":"欧洲的〕桐叶槭﹔桐叶槭木材"},{"en":"a North American tree with broad leaves, or the wood of this tree","cn":"一球悬铃木﹐美国梧桐（木）"}]},"media":{"uk":"media/ldoce/hwd/bre/a/sycamore0205.mp3","us":"media/ldoce/hwd/ame/a/sycamore.mp3","img":["media/thumb/sycamore.jpg"]},"oxford":{"phon":"ˈsɪkəmɔː(r)","pos":"noun","senses":[{"en":"a European tree of the maple family, with leaves that have five points and seeds that are like pairs of wings","cn":"桐叶槭；欧亚槭","g":"[countable, uncountable]","lab":"especially British English"},{"en":"an American plane tree","cn":"西卡莫；（美国）悬铃木","g":"[countable]","lab":"especially North American English"},{"en":"the valuable hard wood of the European sycamore","cn":"槭木","g":"[uncountable]"}]}},"syllable":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"音节","en":"A syllable is a part of a word that contains a single vowel sound and that is pronounced as a unit. So, for example, 'book' has one syllable, and 'reading' has two syllables.","ex":{"en":"We children called her Oma, accenting both syllables.","cn":"我们这群小孩叫她Oma，两个音节都重读。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a word or part of a word which contains a single vowel sound","cn":"音节"}]},"vocab":{"pos":"n","senses":[{"en":"A syllable can be made up of just a vowel — \"a\" can be a syllable — or a vowel and one or more consonants — \" skip \" is one syllable, but three sounds, or phonemes: sk-i-p."}]},"collocations":{"phrases":["ADJ. final, first, last, middle, second, third, etc. | accented, stressed, strong, tonic | unstressed, weak","VERB + SYLLABLE consist of, contain, have words that have three or more syllables | pronounce | put the accent/stress on, stress Put the str","PHRASES stress falls/is on a syllable Normally, the stress falls on the first syllable of a word. | a word of one, two, etc. syllables You'l"]},"media":{"uk":"media/ldoce/hwd/bre/5/syllable0205.mp3","us":"media/ldoce/hwd/ame/8/syllable.mp3"},"examples":[{"en":"‘Potato’ is stressed on the second syllable. * potato","cn":"一词的重音在第二个音节上。"},{"en":"‘Potato’ is stressed on the second syllable.","cn":""}],"oxford":{"phon":"ˈsɪləbl","pos":"noun","senses":[{"en":"any of the units into which a word is divided, containing a vowel sound and usually one or more consonants","cn":"音节","ex":{"en":"a word with two syllables","cn":"双音节单词"}}]}},"syncopation":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(音乐的)切分，切分节奏","en":"Syncopation is the quality that music has when the weak beats in a bar are stressed instead of the strong ones.","ex":{"en":"There was some nice syncopation and it had a good swing to it","cn":"其中有些动听的切分音，而且节奏也很优美。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a rhythm in a line of music in which the beats that are usually weak are emphasized 〔","cn":"音乐的〕切分音﹐切分节奏"}]},"vocab":{"pos":"n","senses":[{"en":"If no one's dancing at the school dance, it might be time to ask the DJ to play some music with more syncopation , or a strong, distinct rhythm that makes you want to move."}]},"media":{"uk":"media/ldoce/hwd/bre/c/syncopation0205.mp3","us":"media/ldoce/hwd/ame/3/laadsyncopation.mp3"},"oxford":{"phon":"ˌsɪŋkəˈpeɪʃn","pos":"noun","senses":[{"en":"a change to the rhythm of a piece of music, so that the strong beats become weak and the weak beats become strong","cn":"调音：改变音乐节奏，使强节奏变弱，弱节奏变强","ex":{"en":"a few jazzy syncopations","cn":"一些爵士切分音"}}]}},"symphonic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"交响乐的;类似交响乐的","en":"Symphonic means relating to or like a symphony."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long piece of music usually in four parts, written for an orchestra","cn":""},{"en":"a large group of classical musicians led by a conductor","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/symphony0205.mp3","us":"media/ldoce/hwd/ame/6/l3symphony.mp3"},"examples":[{"en":"Mozart's symphonic works","cn":"莫扎特的交响乐作品"}],"oxford":{"phon":"sɪmˈfɒnɪk","pos":"adjective","senses":[{"en":"in the form of a symphony; connected with symphonies","cn":"交响乐的：交响乐的形式 与交响乐有关","ex":{"en":"Mozart’s symphonic works","cn":"莫扎特的交响乐作品"}}]}},"syphilis":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"梅毒","en":"Syphilis is a serious disease which is passed on through sexual intercourse."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very serious disease that is passed from one person to another during sexual activity","cn":"梅毒"}]},"media":{"uk":"media/ldoce/hwd/bre/3/syphilis0205.mp3","us":"media/ldoce/hwd/ame/8/syphilis.mp3"},"oxford":{"phon":"ˈsɪfɪlɪs","pos":"noun","senses":[{"en":"a disease that gets worse over a period of time, spreading from the sexual organs to the skin, bones, muscles and brain. It is caught by having sex with a person who already has the disease.","cn":"梅毒"}]}},"synopsis":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(著作或作品的)大纲，提要，概要，梗概","en":"A synopsis is a summary of a longer piece of writing or work.","ex":{"en":"For each title there is a brief synopsis of the book.","cn":"每本书都对应有一个简短的介绍。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short statement that gives only the main ideas and facts of something that has been written or said","cn":""},{"en":"a short statement, especially a written one, that summarizes a statement or piece of writing and contains only the most important points","cn":""},{"en":"a short statement that summarizes a whole subject, situation, or problem in a general way","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Synopsis is a noun meaning summary . Instead of reciting every line of the Shakespeare play you were assigned to read over the weekend, it might be more helpful for your classmates if you give them a synopsis of what happened."}]},"media":{"uk":"media/ldoce/hwd/bre/3/synopsis0205.mp3","us":"media/ldoce/hwd/ame/c/synopsis.mp3"},"examples":[{"en":"a synopsis of the play","cn":"剧情梗概"}],"oxford":{"phon":"sɪˈnɒpsɪs","pos":"noun","senses":[{"en":"a summary of a piece of writing, a play, etc.","cn":"（著作、剧本等的）大纲，提要，概要，梗概","ex":{"en":"The programme gives a brief synopsis of the plot.","cn":"该节目简要介绍了情节。"}}]}},"syntactic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"句法的","en":"Syntactic means relating to syntax.","ex":{"en":"...three common syntactic devices in English.","cn":"英语中 3 个常见的构句方法"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to syntax","cn":"句法的"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41syntactic.mp3","us":"media/ldoce/hwd/ame/f/syntactic.mp3"},"examples":[{"en":"to be syntactically correct","cn":"在句法上正确"},{"en":"syntactic structure","cn":"句法结构"}],"oxford":{"phon":"sɪnˈtæktɪk","pos":"adjective","senses":[{"en":"connected with syntax","cn":"句法的","ex":{"en":"syntactic rules/structures","cn":"句法规则/结构"}}]}},"syrupy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"糖浆般甜腻的;糖浆般黏稠的","en":"Liquid that is syrupy is sweet or thick like syrup."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"缠绵的;过分多情的;煽情的","en":"If you describe something as syrupy, you dislike it because it is too sentimental.","ex":{"en":"...this syrupy film version of Conroy's novel.","cn":"根据康罗伊小说拍成的这一非常煽情的电影"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"thick and sticky like syrup, or containing syrup","cn":"糖浆状的﹔含糖浆的"},{"en":"too nice or kind in a way that seems insincere – used to show disapproval","cn":"甜腻的〔含贬义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41syrupy.mp3","us":"media/ldoce/hwd/ame/0/syrupy.mp3"},"examples":[{"en":"a syrupy romantic novel","cn":"一部缠绵的言情小说"},{"en":"a syrupy liquid","cn":"糖浆般黏稠的液体"}],"oxford":{"phon":"ˈsɪrəpi","pos":"adjective","senses":[{"en":"thick and sticky like syrup; containing syrup","cn":"糖浆般黏稠的；含糖浆的","ex":{"en":"Heat the liquid until it is thick and syrupy.","cn":"将液体加热至浓稠呈糖浆状。"}},{"en":"extremely emotional and romantic and therefore unpleasant; too sentimental","cn":"缠绵的；过分多情的","lab":"disapproving","ex":{"en":"a syrupy romantic novel","cn":"一部过度煽情的言情小说"}}]}},"sympathize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"同情","en":"If you sympathize with someone who is in a bad situation, you show that you are sorry for them.","ex":{"en":"I must tell you how much I sympathize with you for your loss, Professor","cn":"教授，我对您遭受的损失深表同情。"}},{"pos":"VERB 动词","cn":"理解;体谅","en":"If you sympathize with someone's feelings, you understand them and are not critical of them.","ex":{"en":"Some Europeans sympathize with the Americans over the issue","cn":"一些欧洲人在该问题上对美国人表示理解。"}},{"pos":"VERB 动词","cn":"赞同;支持","en":"If you sympathize with a proposal or action, you approve of it and are willing to support it.","ex":{"en":"Most of the people living there sympathized with the guerrillas.","cn":"住在那里的大多数人支持游击队。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to feel sad for someone because you understand their problems","cn":""},{"en":"to feel sad for someone because they have had bad luck or are in a difficult situation","cn":""},{"en":"to realize how someone feels and why they behave the way they do, and be kind to them","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you sympathize , you care about how someone else feels during a time of trouble. If you sympathize with your brother, whose best friend is moving away, you understand why he's feeling sad."}]},"collocations":{"phrases":["ADV. deeply, really I sympathize deeply with his family.","VERB + SYMPATHIZE can/could I can really sympathize with John. | be easy to, be hard not to It is hard not to sympathize with her dilemma.","PREP. with We sympathized with the bereaved family. 2 agree with sb","ADV. entirely, fully","PREP. with I entirely sympathize with this view."]},"media":{"uk":"media/ldoce/hwd/bre/5/sympathize0205.mp3","us":"media/ldoce/hwd/ame/8/sympathize.mp3"},"examples":[{"en":"He has never really sympathized with the aims of Animal Rights activists.","cn":"他从来没有真正赞同过动物权利保护者的目标。"},{"en":"I find it very hard to sympathize with him.","cn":"我觉得很难去同情他。"}],"oxford":{"phon":"ˈsɪmpəθaɪz","pos":"verb","senses":[{"en":"to feel sorry for somebody; to show that you understand and feel sorry about somebody’s problems","cn":"同情","g":"[intransitive, transitive]","ex":{"en":"I find it very hard to sympathize with him.","cn":"我觉得很难去同情他。"}},{"en":"to support somebody/something","cn":"赞同；支持","g":"[intransitive]","ex":{"en":"He has never really sympathized with the aims of Animal Rights activists.","cn":"他从来没有真正赞同过动物权利保护者的目标。"}}]}},"systemic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"系统的;影响全面的;全身的","en":"Systemic means affecting the whole of something.","ex":{"en":"The economy is locked in a systemic crisis.","cn":"经济陷入全面危机。"}},{"pos":"ADJ 形容词","cn":"(化学品或药品)内吸的","en":"Systemic chemicals or drugs are absorbed into the whole of an organism such as a plant or person, rather than being applied to one area."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"affecting the whole of something","cn":"影响全部的；全面性的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something that's systemic affects all parts of something. If every dog at doggy daycare has fleas, it's a systemic problem."}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41systemic.mp3","us":"media/ldoce/hwd/ame/e/systemic.mp3"},"examples":[{"en":"systemic weedkillers","cn":"内吸除草剂"},{"en":"Corruption in the police force is systemic.","cn":"警察部门集体腐败。"}],"oxford":{"phon":"sɪˈstiːmɪk","pos":"adjective","senses":[{"en":"affecting or connected with the whole of something, especially the human body or a society","cn":"（尤指身体或社会）涉及全系统的，系统性的","ex":{"en":"a systemic disease","cn":"全身性疾病"}},{"en":"systemic chemicals or drugs that are used to treat diseases in plants or animals enter the body of the plant or animal and spread to all parts of it","cn":"（农药等）内吸的","ex":{"en":"systemic weedkillers","cn":"内吸除草剂"}}]}},"sybaritic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"贪图享乐的;骄奢淫逸的","en":"Someone who has a sybaritic way of life spends a lot of time relaxing in a luxurious way."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"wanting or enjoying expensive pleasures and comforts","cn":"贪图享受的﹔骄奢淫逸的"}]},"vocab":{"pos":"adj","senses":[{"en":"Because of its endless sybaritic (indulgent or luxurious) amenities, Dubai has emerged in the early 21st century as a vacation destination for the wealthy and ostentatious."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41sybaritic.mp3","us":"media/ldoce/hwd/ame/8/sybaritic.mp3"},"examples":[{"en":"his sybaritic lifestyle","cn":"他骄奢淫逸的生活方式"}],"oxford":{"phon":"ˌsɪbəˈrɪtɪk","pos":"adjective","senses":[{"en":"connected with a desire for pleasure","cn":"贪图享乐的；骄奢淫逸的","ex":{"en":"his sybaritic lifestyle","cn":"他骄奢淫逸的生活方式"}}]}},"symbiotic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"共生的;互惠互利的","en":"A symbiotic relationship is one in which organisms, people, or things exist together in a way that benefits them all.","ex":{"en":"...fungi that have a symbiotic relationship with the trees of these northwestern forests","cn":"与西北部这些森林里的树木存在共生关系的真菌"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a symbiotic relationship is one in which the people, organizations, or living things involved depend on each other 〔","cn":"人﹑组织或生物〕互相依赖的﹐共生的"}]},"vocab":{"pos":"adj","senses":[{"en":"A symbiotic relationship benefits both parties. The two of you have a symbiotic relationship: she fixes your car and you style her hair."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41symbiotic.mp3","us":"media/ldoce/hwd/ame/a/ld41symbiotic.mp3"},"examples":[{"en":"a symbiotic relationship","cn":"一种互惠互利的关系"}],"oxford":{"phon":"ˌsɪmbaɪˈɒtɪk","pos":"adjective","senses":[{"en":"used to describe a relationship between two different living creatures that live close together and depend on each other in particular ways, each getting particular benefits from the other","cn":"共生（关系）","lab":"biology","ex":{"en":"Humans have a symbiotic relationship with trees.","cn":"人类与树木有着共生关系。"}},{"en":"used to describe a relationship between people, companies, etc. that is to the advantage of both","cn":"合作关系；互惠互利的关系","ex":{"en":"The two formed a close friendship and a symbiotic working relationship that lasted half a century.","cn":"两人结下了长达半个世纪的亲密友谊和共生工作关系。"}}]}},"symposium":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"专题讨论会;研讨会","en":"A symposium is a conference in which experts or academics discuss a particular subject.","ex":{"en":"He had been taking part in an international symposium on population.","cn":"他那时正参加一个有关人口问题的国际研讨会。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a formal meeting in which people who know a lot about a particular subject have discussions about it","cn":"专题研讨会﹔专题讨论会"},{"en":"a group of articles on a particular subject collected together in a book","cn":"专题论文集"}]},"vocab":{"pos":"n","senses":[{"en":"A symposium is a public meeting about a topic in which people give presentations. If your knitting club holds a symposium , various knitters will give presentations about anything having to do with knitting."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41symposium.mp3","us":"media/ldoce/hwd/ame/6/symposium.mp3"},"examples":[{"en":"a symposium on women’s health","cn":"女性健康研讨会"}],"oxford":{"phon":"sɪmˈpəʊziəm","pos":"noun","senses":[{"en":"a meeting at which experts have discussions about a particular subject; a small conference","cn":"专题讨论会；研讨会；小型讨论会"}]}},"synonym":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同义词","en":"A synonym is a word or expression which means the same as another word or expression.","ex":{"en":"The term 'industrial democracy' is often used as a synonym for worker participation.","cn":"“工业民主”这个词常被用作“工人参与”的同义词。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a word with the same meaning as another word in the same language","cn":"同义词"}]},"vocab":{"pos":"n","senses":[{"en":"A synonym is a word that means the same thing as another word. If you replace a word in a sentence with its synonym, the meaning of the sentence won't really change that much."}]},"media":{"uk":"media/ldoce/hwd/bre/3/synonym0205.mp3","us":"media/ldoce/hwd/ame/2/synonym.mp3"},"examples":[{"en":"‘Big’ and ‘large’ are synonyms. * big","cn":"和 large 是同义词。"},{"en":"‘Big’ and ‘large’ are synonyms.","cn":""}],"oxford":{"phon":"ˈsɪnənɪm","pos":"noun","senses":[{"en":"a word or expression that has the same or nearly the same meaning as another in the same language","cn":"同义词","ex":{"en":"‘Big’ and ‘large’ are synonyms.","cn":"big 和 large 是同义词。"}}]}},"synonymous":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(与…)关系紧密的;等同(于)…的;互为依存的","en":"If you say that one thing is synonymous with another, you mean that the two things are very closely associated with each other so that one suggests the other or one cannot exist without the other.","ex":{"en":"Paris has always been synonymous with elegance, luxury and style","cn":"巴黎一直是优雅、奢华和时尚的代名词。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is synonymous with something else is considered to be very closely connected with it","cn":"与…密切相关的"},{"en":"two words that are synonymous have the same meaning 〔","cn":"单词〕同义的"}]},"vocab":{"pos":"adj","senses":[{"en":"If two words are synonymous , they mean the same thing. You tried to convince her that \"love\" and \"chocolate\" were not synonymous , but it was no use."}]},"collocations":{"phrases":["VERBS be, seem | become | remain | make sth His deeds had made his name synonymous with victory. | consider sth, regard sth as, see sth as, ","ADV. completely, exactly | almost, largely, more or less, roughly, virtually","PREP. with Until the late eighteenth century, &lsquo;opera&rsquo; was almost synonymous with Italian opera."]},"media":{"uk":"media/ldoce/hwd/bre/6/synonymous0205.mp3","us":"media/ldoce/hwd/ame/0/synonymous.mp3"},"examples":[{"en":"Wealth is not necessarily synonymous with happiness.","cn":"财富未必等同于幸福。"},{"en":"Nixon’s name has become synonymous with political scandal.","cn":"尼克松的名字成了政治丑闻的代名词。"}],"oxford":{"phon":"sɪˈnɒnɪməs","pos":"adjective","senses":[{"en":"having the same, or nearly the same, meaning","cn":"同义的","ex":{"en":"Few words are truly synonymous.","cn":"很少有真正的同义词。"}},{"en":"so closely connected with something that the two things appear to be the same","cn":"等同于…的","ex":{"en":"Wealth is not necessarily synonymous with happiness.","cn":"财富未必等同于幸福。"}}]}},"synapse":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(神经元的)突触","en":"A synapse is one of the points in the nervous system at which a signal passes from one nerve cell to another."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the place where nerve cells meet, especially in the brain 〔","cn":"神经元的〕突触"}]},"vocab":{"pos":"n","senses":[{"en":"A synapse is the tiny gap across which a nerve cell, or neuron, can send an impulse to another neuron. When all your synapses are firing, you're focused and your mind feels electric."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld44synapse.mp3","us":"media/ldoce/hwd/ame/f/ld44synapse.mp3"},"examples":[{"en":"the synaptic membranes","cn":"突触膜"}],"oxford":{"phon":"ˈsaɪnæps","pos":"noun","senses":[{"en":"a connection between two nerve cells","cn":"（神经元的）突触","ex":{"en":"Information from one neuron flows to another neuron across a synapse.","cn":"来自一个神经元的信息通过突触流向另一个神经元。"}}]}},"sylvan":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"森林的;树木的","en":"Sylvan is used to describe things that have an association with woods and trees."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to a forest or trees","cn":"森林的﹔树木的"}]},"vocab":{"pos":"adj n","senses":[{"en":"The adjective sylvan refers to a shady, wooded area. The word suggests a peaceful, pleasant feeling, as though you were far away from the noise of modern life."}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41sylvan.mp3","us":"media/ldoce/hwd/ame/1/laadsylvan.mp3"},"oxford":{"phon":"ˈsɪlvən","pos":"adjective","senses":[{"en":"connected with forests and trees","cn":"森林的；树木的","ex":{"en":"sylvan surroundings","cn":"森林环境"}}]}},"symbolize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"象征;代表","en":"If one thing symbolizes another, it is used or regarded as a symbol of it.","ex":{"en":"The fall of the Berlin Wall symbolised the end of the Cold War between East and West.","cn":"柏林墙的倒塌象征着东西方冷战的结束。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to have a particular meaning - use this about words, signs, or statements","cn":""},{"en":"if a letter or group of letters stands for a word, name, or number, it is a short way of saying or writing it","cn":""},{"en":"if a shape, letter, object etc represents something, it is used as a sign for that thing in a map, plan, calculation etc","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Use the verb symbolize when you use an image, shape, color, or other simple visual to stand for something else, like when you wear black to symbolize that you're mourning a loss."}]},"media":{"uk":"media/ldoce/hwd/bre/a/symbolize0205.mp3","us":"media/ldoce/hwd/ame/7/symbolize.mp3"},"examples":[{"en":"He came to symbolize his country's struggle for independence.","cn":"他逐渐成为祖国为争取独立而斗争的象征。"},{"en":"The use of light and dark symbolizes good and evil.","cn":"用光明与黑暗来象征善与恶。"}],"oxford":{"phon":"ˈsɪmbəlaɪz","pos":"verb","senses":[{"en":"to be a symbol of something","cn":"象征；是…的象征；代表","ex":{"en":"The use of light and dark symbolizes good and evil.","cn":"用光明与黑暗来象征善与恶。"}}]}},"synchronize":{"collins":{"senses":[{"pos":"V-RECIP-ERG","cn":"(使)同步;(使)在时间上一致;(使)同速进行","en":"If you synchronize two activities, processes, or movements, or if you synchronize one activity, process, or movement with another, you cause them to happen at the same time and speed as each other.","ex":{"en":"It was virtually impossible to synchronise our lives so as to take holidays and weekends together","cn":"想让我们的生活步调保持一致好一起去度假和过周末几乎是不可能的事。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to happen at exactly the same time, or to arrange for two or more actions to happen at exactly the same time （","cn":"使）同时发生﹐（使）同步"},{"en":"to make two or more watches show exactly the same time","cn":"校准〔两个或多个〕钟表﹔对表"}]},"vocab":{"pos":"v","senses":[{"en":"When you synchronize things, you make them happen at the same time. If you have rhythm, you can synchronize your dance moves with the beat of the music. If not, stay off the dance floor."}]},"collocations":{"phrases":["ADV. carefully | exactly, precisely","PREP. with The timing of the gun was precisely synchronized with the turning of the plane's propeller."]},"media":{"uk":"media/ldoce/hwd/bre/d/synchronize0205.mp3","us":"media/ldoce/hwd/ame/e/synchronize.mp3"},"examples":[{"en":"The sound track did not synchronize with the action.","cn":"声迹与动作不同步。"},{"en":"Let's synchronize our watches (= make them show exactly the same time).","cn":"咱们对一下表吧。"}],"oxford":{"phon":"ˈsɪŋkrənaɪz","pos":"verb","senses":[{"en":"to happen at the same time or to move at the same speed as something; to make something do this","cn":"（使）同步，在时间上一致，同速进行","g":"[intransitive, transitive]","ex":{"en":"The soundtrack did not synchronize with the action.","cn":"声迹与动作不同步。"}},{"en":"to link data files between one computer or mobile device and another so that the information in the files on both machines is the same","cn":"使同步，使一致（使数据在不同的计算机或移动电子设备上同步更新）","g":"[transitive]","ex":{"en":"You can use the technology to synchronize data between computers.","cn":"利用该技术可在计算机之间同步数据。"}}]}},"synagogue":{"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"犹太会堂;犹太教堂","en":"A synagogue is a building where Jewish people meet to worship or to study their religion."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a building where Jewish people meet for religious worship","cn":"犹太会堂﹐犹太教堂"}]},"vocab":{"pos":"n","senses":[{"en":"A synagogue is a Jewish house of worship."}]},"media":{"uk":"media/ldoce/hwd/bre/a/synagogue0205.mp3","us":"media/ldoce/hwd/ame/1/synagogue.mp3"},"oxford":{"phon":"ˈsɪnəɡɒɡ","pos":"noun","senses":[{"en":"a building where Jewish people meet for religious worship and teaching","cn":"犹太会堂；犹太教堂","ex":{"en":"They went to synagogue every Saturday.","cn":"他们每个星期六去犹太教堂。"}}]}},"syrup":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"糖水(有时加果汁)","en":"Syrup is a sweet liquid made by cooking sugar with water, and sometimes with fruit juice as well.","ex":{"en":"...canned fruit with sugary syrup.","cn":"糖水水果罐头"}},{"pos":"N-UNCOUNT 不可数名词","cn":"糖浆","en":"Syrup is a very sweet thick liquid made from sugar.","ex":{"en":"...a heavy syrup pudding.","cn":"放入大量糖浆的布丁"}},{"pos":"N-MASS 物质名词","cn":"药用糖浆;糖浆剂","en":"Syrup is a medicine in the form of a thick, sweet liquid.","ex":{"en":"...cough syrup.","cn":"止咳糖浆"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a thick sticky sweet liquid, eaten on top of or mixed with other foods","cn":"糖浆"},{"en":"sweet liquid made from sugar and water, used in cans of fruit 〔","cn":"用于罐头水果的〕糖水"}]},"media":{"uk":"media/ldoce/hwd/bre/a/syrup0205.mp3","us":"media/ldoce/hwd/ame/c/syrup.mp3"},"examples":[{"en":"pears in syrup","cn":"糖水梨"},{"en":"ice cream and maple syrup","cn":"枫糖浆冰激凌"}],"oxford":{"phon":"ˈsɪrəp","pos":"noun","senses":[{"en":"a sweet liquid made from sugar and water, often used in cans of fruit","cn":"糖水（常用于水果罐头）","ex":{"en":"pears in syrup","cn":"糖水梨"}},{"en":"any thick sweet liquid made with sugar, used especially as a sauce","cn":"糖浆"}]}},"syrian":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"叙利亚的;叙利亚人的;叙利亚文化的","en":"Syrian means belonging or relating to Syria, or to its people or culture.","ex":{"en":"...the Syrian capital of Damascus.","cn":"叙利亚首都大马士革"}},{"pos":"N-COUNT 可数名词","cn":"叙利亚人;叙利亚裔人","en":"A Syrian is a Syrian citizen, or a person of Syrian origin.","ex":{"en":"The crew-members were Syrians.","cn":"乘务员是叙利亚人。"}}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a country in the MIddle East, which is south of Turkey and west of Iraq. Population 22,457,336 (2014). Capital: Damascus. Since 2011, Syria has been involved in a civil war .","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/p028-000011805.mp3","us":"media/ldoce/hwd/ame/4/p028-000011805.mp3"},"oxford":{"phon":"ˈsɪriən","pos":"noun, adjective","senses":[{"en":"(a person) from Syria","cn":"叙利亚人；叙利亚的；叙利亚人的"}]}},"syndicate":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"辛迪加;私人联合会;企业联合组织","en":"A syndicate is an association of people or organizations that is formed for business purposes or in order to carry out a project.","ex":{"en":"They formed a syndicate to buy the car in which they competed in the race.","cn":"他们合伙买下了他们参加赛车时用的那部车。"}},{"pos":"VERB 动词","cn":"把(新闻或电视节目)同时出售给多家媒体(供其发表或播放)","en":"When newspaper articles or television programmes are syndicated, they are sold to several different newspapers or television stations, who then publish the articles or broadcast the programmes.","ex":{"en":"Today his programme is syndicated to 500 stations","cn":"今天他的节目将在 500 多家电视台播出。"}},{"pos":"N-COUNT 可数名词","cn":"(报业)辛迪加，巨头","en":"A press syndicate is a group of newspapers or magazines that are all owned by the same person or company."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of criminals who work together","cn":""},{"en":"a group of people who work together and organize an illegal trade, especially in something such as drugs or weapons","cn":""},{"en":"a large and powerful organization that controls illegal businesses and criminal activities","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A syndicate is a group of corporations working for a common interest. A syndicate might collectively raise money for a real estate project. A syndicate sometimes has a criminal side — it can also describe a similar alliance of gangsters."}]},"collocations":{"phrases":["ADJ. crime, criminal, drug/drugs, smuggling | banking, insurance | lottery, pools","VERB + SYNDICATE form | run | join","PREP. in a/the ~ I'm in a lottery syndicate at work.","PHRASES a member of a syndicate"]},"media":{"uk":"media/ldoce/hwd/bre/0/syndicate_n0205.mp3","us":"media/ldoce/hwd/ame/6/l3syndicate.mp3"},"examples":[{"en":"His column is syndicated throughout the world.","cn":"他的专栏文章在世界各地的报刊发表。"},{"en":"His column is syndicated throughout America.","cn":"他的专栏文章在全美各地的报刊发表。"}],"oxford":{"phon":"ˈsɪndɪkət","pos":"noun","senses":[{"en":"a group of people or companies who work together and help each other in order to achieve a particular aim","cn":"辛迪加；企业联合组织；财团；私人联合会","ex":{"en":"a crime syndicate","cn":"犯罪集团"}},{"en":"to sell an article, a photograph, a television programme, etc. to several different newspapers, etc.","cn":"把（文章、照片、电视节目等）出售给多个媒体","ex":{"en":"His column is syndicated throughout the world.","cn":"他的专栏文章在世界各地的报刊发表。"},"pos":"verb"}]}},"synod":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"教会会议","en":"A synod is a special council of members of a Church, which meets regularly to discuss religious issues."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an important meeting of church members","cn":"教会会议"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41synod.mp3","us":"media/ldoce/hwd/ame/a/synod.mp3"},"oxford":{"phon":"ˈsɪnəd","pos":"noun","senses":[{"en":"an official meeting of Church members to discuss religious matters and make important decisions","cn":"教会会议","ex":{"en":"the General Synod of the Church of England","cn":"英国国教总会"}}]}},"synergy":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(两个或多个组织共同协作后产生的)协同增效作用,协同作用","en":"If there is synergy between two or more organizations or groups, they are more successful when they work together than when they work separately.","ex":{"en":"Of course, there's quite obviously a lot of synergy between the two companies","cn":"当然，这两家公司间非常明显地产生了巨大的协同效应。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the additional effectiveness when two or more companies or people combine and work together","cn":"协同作用﹐协同增效"}]},"vocab":{"pos":"n","senses":[{"en":"You write the lyrics and your friend composes the music. Separately each of you is pretty good, but together you’ve got a mega-hit song. That’s synergy — working together to create something greater than either of you could do alone."}]},"media":{"uk":"media/ldoce/hwd/bre/f/synergy0205.mp3","us":"media/ldoce/hwd/ame/6/laadsynergy.mp3"},"oxford":{"phon":"ˈsɪnədʒi","pos":"noun","senses":[{"en":"the extra energy, power, success, etc. that is achieved by two or more people, companies or elements working together, instead of on their own","cn":"协同作用，协同增效作用（多方共同协作所产生的效果优于各自单独行动的效果）","ex":{"en":"Managing effective teams is a matter of achieving synergy between the individual members.","cn":"管理有效的团队就是在各个成员之间实现协同作用。"}}]}},"symptomatic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"作为症状的;作为征候的;表明…的","en":"If something is symptomatic of something else, especially something bad, it is a sign of it.","ex":{"en":"The city's problems are symptomatic of the crisis that is spreading throughout the country.","cn":"该市的问题是正在全国蔓延的危机的征兆显现。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a fact or achievement does not say much for someone or something, it shows very clearly that they are not as good, skilful etc as they should be","cn":""},{"en":"if a bad situation or a bad result is a reflection on someone or something, it shows their character, abilities, or qualities are not very good, because the bad situation or result is their fault","cn":""},{"en":"if an action or event reflects badly on someone, it shows that they have bad qualities, and this makes people's opinion of them become worse","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Anything symptomatic relates to the symptoms of a disease. If you're symptomatic , you might be sick."}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41symptomatic.mp3","us":"media/ldoce/hwd/ame/0/symptomatic.mp3"},"examples":[{"en":"These disagreements are symptomatic of the tensions within the party.","cn":"出现意见分歧表明该党内部的关系紧张。"},{"en":"a symptomatic infection","cn":"有症状感染"}],"oxford":{"phon":"ˌsɪmptəˈmætɪk","pos":"adjective","senses":[{"en":"being a sign of an illness or a problem","cn":"作为症状的；（有）症状的；作为征候的","ex":{"en":"a symptomatic infection","cn":"有症状感染"}}]}},"sycophantic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"阿谀奉承的;谄媚的;拍马屁的","en":"If you describe someone as sycophantic, you disapprove of them because they flatter people who are more important and powerful than they are in order to gain an advantage for themselves.","ex":{"en":"...his clique of sycophantic friends","cn":"他那些互相吹捧的朋党"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"praising important or powerful people too much because you want to get something from them – used to show disapproval","cn":"溜须拍马的﹐阿谀奉承的"}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective sycophantic is perfect for describing someone who uses flattery to get what they want. The sycophantic guy in your biology class might compliment the professor on her fabulous shoes as he hands in his lab report."}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41sycophantic.mp3","us":"media/ldoce/hwd/ame/7/ld41sycophantic.mp3"},"examples":[{"en":"a sycophantic review","cn":"献媚奉承的评论"},{"en":"sycophantic journalists","cn":"好溜须拍马的新闻记者"}],"oxford":{"phon":"ˌsɪkəˈfæntɪk","pos":"adjective","senses":[{"en":"praising important or powerful people too much and in a way that is not sincere, especially in order to get something from them","cn":"阿谀奉承的人；谄媚者；拍马者","ex":{"en":"a sycophantic review","cn":"献媚奉承的评论"}}]}},"synthesis":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"综合;结合;结合体","en":"A synthesis of different ideas or styles is a mixture or combination of these ideas or styles.","ex":{"en":"His novels are a rich synthesis of Balkan history and mythology","cn":"他的小说融合了大量巴尔干半岛的历史和神话故事。"}},{"pos":"N-VAR 可变名词","cn":"(通过化学或生物反应进行的)合成","en":"The synthesis of a substance is the production of it by means of chemical or biological reactions.","ex":{"en":"...the genes that regulate the synthesis of these compounds","cn":"控制这些化合物合成的基因"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"several different substances, ideas, qualities etc that have been put together, especially so that they form one thing","cn":""},{"en":"two or more different things, substances etc that are used together or work together","cn":""},{"en":"a mixture of two or more things, qualities, or characteristics, especially ones that combine successfully or in a pleasant way","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Synthesis is the act of combining elements to form something new. If you describe your bedroom decor as a synthesis of Andy Warhol and Punk Rock, we'll know you mean a mixture of these two styles."}]},"media":{"uk":"media/ldoce/hwd/bre/7/synthesis0205.mp3","us":"media/ldoce/hwd/ame/1/synthesis.mp3"},"examples":[{"en":"a synthesis of traditional and modern values","cn":"传统价值观和现代价值观的综合体"},{"en":"the synthesis of art with everyday life","cn":"艺术与日常生活的结合"}],"oxford":{"phon":"ˈsɪnθəsɪs","pos":"noun","senses":[{"en":"the act of combining separate ideas, beliefs, styles, etc.; a mixture or combination of ideas, beliefs, styles, etc.","cn":"综合；结合；综合体","g":"[uncountable, countable]","ex":{"en":"the synthesis of art with everyday life","cn":"艺术与日常生活的结合"}},{"en":"the natural chemical production of a substance in animals and plants","cn":"（物质在动植物体内的）合成","g":"[uncountable]","lab":"specialist","ex":{"en":"protein synthesis","cn":"蛋白质的合成"}},{"en":"the artificial production of a substance that is present naturally in animals and plants","cn":"（人工的）合成","g":"[uncountable]","lab":"specialist","ex":{"en":"the synthesis of penicillin","cn":"青霉素的合成"}},{"en":"the production of sounds, music or speech by electronic means","cn":"（用电子手段对声音、音乐或语音的）合成","g":"[uncountable]","lab":"specialist"}]}},"symbolism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"象征手法;象征主义","en":"Symbolism is the use of symbols in order to represent something.","ex":{"en":"The scene is so rich in symbolism that any explanation risks spoiling the effect.","cn":"该场景具有丰富的象征意义，任何解释都可能破坏其效果。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"象征意义;象征","en":"You can refer to the symbolism of an event or action when it seems to show something important about a situation.","ex":{"en":"The symbolism of every gesture will be of vital importance during the short state visit.","cn":"在这次短暂的国事访问期间，一举一动都将有着至关重要的象征意义。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the use of symbols to represent ideas or qualities","cn":"象征主义[手法]"}]},"vocab":{"pos":"n","senses":[{"en":"When you come across objects in a painting or story that stand for a concept, the artist or author is using symbolism to convey ideas."}]},"collocations":{"phrases":["ADJ. expressive, rich | sound Sound symbolism means that we can often guess the meaning of a word from its sound. | mythological, pagan, rel","VERB + SYMBOLISM be full of, be rich in, contain Christian churches are still full of pagan symbolism. | interpret, understand"]},"media":{"uk":"media/ldoce/hwd/bre/6/symbolism0205.mp3","us":"media/ldoce/hwd/ame/c/symbolism.mp3"},"examples":[{"en":"the symbolist poet Rimbaud","cn":"象征主义诗人兰波"},{"en":"religious symbolism","cn":"宗教象征主义"}],"oxford":{"phon":"ˈsɪmbəlɪzəm","pos":"noun","senses":[{"en":"the use of symbols to represent ideas, especially in art and literature","cn":"（尤指文艺中的）象征主义，象征手法","lab":"US English","ex":{"en":"poetry full of religious symbolism","cn":"用大量象征手法表现宗教色彩的诗篇。"}}]}},"symbolise":{"lemma":"symbolize"},"symmetry":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(形状、设计或结构的)对称，匀称","en":"Something that has symmetry is symmetrical in shape, design, or structure.","ex":{"en":"...the incredible beauty and symmetry of a snowflake","cn":"雪花难以置信的美丽和对称"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(数量的)相等，相当","en":"Symmetry in a relationship or agreement is the fact of both sides giving and receiving an equal amount.","ex":{"en":"The superpowers pledged to maintain symmetry in their arms shipments.","cn":"超级大国承诺在武器运输方面要保持数量均衡。"}},{"pos":"N-VAR 可变名词","cn":"(国家、机构、局势的)相似,相仿","en":"You can refer to symmetry between countries, institutions, or situations if you think that there is a close similarity between them.","ex":{"en":"He said that Britain would not rejoin the ERM 'until there is much greater symmetry between our economy and other European economies.'","cn":"他说在英国经济与其他欧洲国家的经济实现更大的趋同性之前，英国不会重新加入欧洲汇率机制。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the quality of being symmetrical","cn":"对称"},{"en":"the quality that a situation has when two events or actions seem to be balanced or equal in some way","cn":"相似﹔相等"}]},"vocab":{"pos":"n","senses":[{"en":"Things that have symmetry are balanced, with each side reflecting the other. A human body has such complex symmetry, from eyes, ears, and nostrils to arms, legs, and feet, that even a minor injury can make a body look unbalanced."}]},"collocations":{"phrases":["ADJ. perfect, pleasing","VERB + SYMMETRY break, destroy The trees break the symmetry of the painting.","PREP. ~ between the symmetry between different forces","PHRASES an axis/a line of symmetry"]},"media":{"uk":"media/ldoce/hwd/bre/2/symmetry0205.mp3","us":"media/ldoce/hwd/ame/b/symmetry.mp3"},"examples":[{"en":"the perfect symmetry of the garden design","cn":"花园图案的完全对称"},{"en":"the increasing symmetry between men's and women's jobs","cn":"男女职业的日渐趋同"}],"oxford":{"phon":"ˈsɪmətri","pos":"noun","senses":[{"en":"the exact match in size and shape between two halves, parts or sides of something","cn":"对称","ex":{"en":"the perfect symmetry of the garden design","cn":"花园图案的完全对称"}},{"en":"the quality of being very similar or equal","cn":"相似；相仿；相等","ex":{"en":"the increasing symmetry between men’s and women’s jobs","cn":"男女职业的日渐趋同"}}]}},"syphon":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a British spelling of siphon siphon","cn":"的英式拼法"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41syphon.mp3","us":"media/ldoce/hwd/ame/5/ld41syphon.mp3"},"oxford":{"phon":"ˈsaɪfn","pos":"noun","senses":[{"en":"a tube that is used to move liquid from one container down into another, lower container","cn":"虹吸管"},{"en":"to move a liquid from one container to another, using a syphon","cn":"虹吸管：使用虹吸管将液体从一个容器移到另一个容器","ex":{"en":"I syphoned the gasoline out of the car into a can.","cn":"我把车里的汽油吸进罐子里。"},"pos":"verb"},{"en":"to remove money from one place and move it to another, especially dishonestly or illegally","cn":"（尤指私自或非法）抽走，转移（钱）","lab":"informal","ex":{"en":"She has been accused of syphoning off thousands of pounds from the company into her own bank account.","cn":"她被指控从公司挪用数千英镑存入自己的银行账户。"},"pos":"verb"}]}},"sycophancy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"阿谀奉承;溜须拍马","en":"Sycophancy is the quality or action of being sycophantic."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"praising important or powerful people too much because you want to get something from them – used to show disapproval","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41sycophantic.mp3","us":"media/ldoce/hwd/ame/7/ld41sycophantic.mp3"},"oxford":{"phon":"ˈsɪkəfənsi","pos":"noun","senses":[{"en":"behaviour that praises important or powerful people too much and in a way that is not sincere, especially in order to get something from them","cn":"阿谀奉承的人；谄媚者；拍马者"}]}},"sycophant":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"阿谀奉承的人;谄媚者;马屁精","en":"A sycophant is a person who behaves in a sycophantic way.","ex":{"en":"...a dictator surrounded by sycophants, frightened to tell him what he may not like.","cn":"被一群不敢谏言的佞臣簇拥的独裁者"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who praises powerful people too much because they want to get something from them – used to show disapproval","cn":"阿谀奉承者﹐谄媚者﹐拍马屁者"}]},"vocab":{"pos":"n","senses":[{"en":"A sycophant is a person who tries to win favor from wealthy or influential people by flattering them. Also known as brown-nosers, teacher's pets or suck-ups."}]},"media":{"uk":"media/ldoce/hwd/bre/c/sycophant0205.mp3","us":"media/ldoce/hwd/ame/b/sycophant.mp3"},"examples":[{"en":"a sycophantic review","cn":"献媚奉承的评论"},{"en":"a dictator surrounded by sycophants","cn":"被阿谀奉承者包围的独裁者"}],"oxford":{"phon":"ˈsɪkəfænt","pos":"noun","senses":[{"en":"a person who praises important or powerful people too much and in a way that is not sincere, especially in order to get something from them","cn":"阿谀奉承的人；谄媚者；拍马者"}]}},"sydney":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the largest city in Australia, which is the capital of the state of New South Wales and an important financial, industrial, and educational centre. It is known especially for the Sydney Harbour Bridge and for the Sydney Opera House, an unusual modern building ","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/p028-000011801.mp3","us":"media/ldoce/hwd/ame/5/p028-000011801.mp3"},"oxford":{"phon":"ˈsɪdni","pos":"","senses":[{"en":"the capital of New South Wales in south-eastern Australia. It was the first British settlement in Australia and is the country's largest city and chief port. It has a fine natural harbour, crossed by the Sydney Harbour Bridge (opened in 1932), and a striking opera house (opened in 1973).","cn":"悉尼（澳大利亚东南部新南威尔士州首府。是英国人在澳大利亚的第一个定居点，现为该国最大城市和主要港口。悉尼有一个天然良港，悉尼海港大桥（1932 年开通）横跨港口。悉尼歌剧院（1973 年投入使用）是引人注目的景观）"},{"en":"an urban area on Cape Breton Island in the Canadian province of Nova Scotia","cn":"悉尼（加拿大新斯科舍省布雷顿角岛上的一处城区）"}]}},"syringe":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"注射器","en":"A syringe is a small tube with a thin hollow needle at the end. Syringes are used for putting liquids into things and for taking liquids out, for example for injecting drugs or for taking blood from someone's body."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an instrument for taking blood from someone’s body or putting liquid, drugs etc into it, consisting of a hollow plastic tube and a needle","cn":"注射器﹐注射筒"},{"en":"to clean something with a syringe, for example your ears 〔","cn":"用注射器〕灌洗﹐冲洗"}]},"vocab":{"pos":"n v","senses":[{"en":"A syringe is used, usually by a doctor or nurse, to inject or withdraw a fluid from your body."}]},"collocations":{"phrases":["ADJ. clean, sterile | used a beach scattered with used syringes | disposable | hypodermic","VERB + SYRINGE fill, prepare | draw sth into The doctor drew a dose of morphia into the syringe. | share","SYRINGE + NOUN exchange a syringe exchange scheme"]},"media":{"img":["media/ldoce/img/needle_syringe.jpg","media/thumb/syringe.jpg"],"uk":"media/ldoce/hwd/bre/d/syringe_n0205.mp3","us":"media/ldoce/hwd/ame/3/syringe1.mp3"},"examples":[{"en":"I had my ears syringed.","cn":"我的耳朵已用注射器清洗干净。"}],"oxford":{"phon":"sɪˈrɪndʒ","pos":"noun","senses":[{"en":"a plastic or glass tube with a long hollow needle that is used for putting drugs, etc. into a person’s body or for taking a small amount of blood from a person","cn":"（皮下）注射器","ex":{"en":"a beach scattered with used syringes","cn":"丢满了废弃注射器的沙滩"}},{"en":"a plastic or glass tube with a rubber part at the end, used for taking liquid in and then pushing it out","cn":"吸管；唧筒"},{"en":"to clean somebody’s ear, a wound, etc. by spraying liquid into it with a syringe","cn":"用注射器清洗（耳朵、伤口等）","ex":{"en":"I had my ears syringed.","cn":"我的耳朵已用注射器清洗干净。"},"pos":"verb"}]}},"syncopated":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"切分的，切分音乐的(节拍强弱倒置)","en":"In syncopated music, the weak beats in the bar are stressed instead of the strong beats.","ex":{"en":"Some spirituals are based on syncopated rhythms.","cn":"有一些圣歌以切分节奏为主旋律。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"syncopated music has a rhythm in which the beats that are usually weak are emphasized","cn":"切分的﹐切分音乐的〔节拍强弱倒置〕"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41syncopated.mp3","us":"media/ldoce/hwd/ame/3/ld41syncopated.mp3"},"oxford":{"phon":"ˈsɪŋkəpeɪtɪd","pos":"adjective","senses":[{"en":"in syncopated rhythm the strong beats are made weak and the weak beats are made strong","cn":"切分的，切分音乐的（节拍强弱倒置）"}]}},"synthesize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(通过化学或生物反应)合成","en":"To synthesize a substance means to produce it by means of chemical or biological reactions.","ex":{"en":"After extensive research, Albert Hoffman first succeeded in synthesizing the acid in 1938","cn":"经过大量研究，艾伯特·霍夫曼于 1938 年首次成功合成了该酸性物质。"}},{"pos":"VERB 动词","cn":"综合;把…合为一体","en":"If you synthesize different ideas, facts, or experiences, you combine them to form a single idea or impression.","ex":{"en":"The movement synthesised elements of modern art that hadn't been brought together before, such as Cubism and Surrealism.","cn":"该运动综合了立体派和超现实主义等以前从未同时出现过的现代艺术元素。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something by combining different things or substances","cn":"合成"},{"en":"to combine separate things into a complete whole","cn":"使融合"},{"en":"to produce sounds, speech, or music electronically 〔","cn":"用电子方式〕合成〔声音﹑语音或音乐〕"}]},"vocab":{"pos":"v","senses":[{"en":"When you synthesize, you combine two or more things to create something more complex. It's becoming more common for doctors these days to synthesize Eastern and Western approaches to medicine."}]},"media":{"uk":"media/ldoce/hwd/bre/0/synthesize0205.mp3","us":"media/ldoce/hwd/ame/8/synthesize.mp3"},"examples":[{"en":"DDT is a pesticide that was first synthesized in 1874.","cn":"滴滴涕是最初合成于1874年的杀虫剂。"}],"oxford":{"phon":"ˈsɪnθəsaɪz","pos":"verb","senses":[{"en":"to produce a substance by means of chemical or biological processes","cn":"（通过化学手段或生物过程）合成","lab":"specialist"},{"en":"to produce sounds, music or speech using electronic equipment","cn":"（用电子设备）合成（声音、音乐或语音）"},{"en":"to combine separate ideas, beliefs, styles, etc.","cn":"综合","ex":{"en":"Students learn to synthesize information and search for what is relevant.","cn":"学生学习如何综合信息并查找相关内容。"}}]}},"synthesizer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"音响合成器","en":"A synthesizer is an electronic machine that produces speech, music, or other sounds, usually by combining individual syllables or sounds that have been previously recorded.","ex":{"en":"Now he can only communicate through a voice synthesiser.","cn":"现在他只能通过声音合成器与人沟通。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an electronic instrument that produces the sounds of various musical instruments 〔","cn":"电子〕音响合成器﹔电声合成器"}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdesynthesizer.mp3","us":"media/ldoce/hwd/ame/5/synthesizer.mp3"},"examples":[{"en":"a speech synthesizer","cn":"语音合成器"}],"oxford":{"phon":"ˈsɪnθəsaɪzə(r)","pos":"noun","senses":[{"en":"an electronic machine for producing different sounds. Synthesizers are used as musical instruments, especially for copying the sounds of other instruments, and for copying speech sounds.","cn":"音响合成器","ex":{"en":"a speech synthesizer","cn":"语音合成器"}}]}},"synesthesia":{"vocab":{"pos":"n","senses":[{"en":"Synesthesia is a condition that happens when a sense, such as sight, triggers another sense, like smell, at the same time. For someone with synesthesia , each letter of the alphabet might have a different odor. Cool!"}]}}});
